function globToRegExp(glob) {
  var out = '^';
  for (var i = 0; i < glob.length; i++) {
    var c = glob[i];
    if (c === '*') out += '[^.]+';
    else if (c === '.') out += '\\.';
    else out += c.replace(/[-/\\^$+?()[\]{}|]/g, '\\$&');
  }
  return new RegExp(out + '$');
}

function shouldPublish(ref, tagGlob) {
  if (ref.indexOf('refs/tags/') !== 0) return false; // branch push never publishes
  var name = ref.slice('refs/tags/'.length);
  return globToRegExp(tagGlob).test(name);
}

var glob = 'v*.*.*';
var refs = [
  'refs/heads/main',
  'refs/heads/feature/login',
  'refs/tags/v1.4.0',
  'refs/tags/v2.0.0-rc.1',
  'refs/tags/nightly'
];
for (var i = 0; i < refs.length; i++) {
  console.log((shouldPublish(refs[i], glob) ? 'PUBLISH ' : 'SKIP    ') + refs[i]);
}
